    walkAct: 'walk',
    tourPoint: 'wave',
    tourRest: ['spinRoll', 'hopSeq', 'bowSeq', 'handsBack', 'curtsy', 'bow', 'nod', 'hug', 'wave', 'sit', 'look'],
